// Independent actual standard-library Quote, not a Rust-produced golden.
package main
import("crypto/sha256";"encoding/binary";"encoding/hex";"encoding/json";"os";"runtime";"strconv";"unicode/utf8")
func main(){b,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};var cases []struct{ID string `json:"id"`;Input string `json:"input"`};if e=json.Unmarshal(b,&cases);e!=nil{panic(e)};enc:=json.NewEncoder(os.Stdout);for _,c:=range cases{if e=enc.Encode(map[string]any{"id":c.ID,"quoted":strconv.Quote(c.Input)});e!=nil{panic(e)}};h:=sha256.New();var count uint64;for cp:=uint32(0);cp<=utf8.MaxRune;cp++{if !utf8.ValidRune(rune(cp)){continue};var b[4]byte;binary.LittleEndian.PutUint32(b[:],cp);h.Write(b[:]);q:=[]byte(strconv.Quote(string(rune(cp))));binary.LittleEndian.PutUint32(b[:],uint32(len(q)));h.Write(b[:]);h.Write(q);count++};if e=enc.Encode(map[string]any{"id":"all-valid-unicode","count":count,"sha256":hex.EncodeToString(h.Sum(nil)),"go_version":runtime.Version()});e!=nil{panic(e)}}
